/**
 * Assessment → improvement analysis → roadmap. Every result is generated by
 * the career agent from the stored profile + parsed resume, then persisted so
 * it survives refreshes and is only regenerated on request.
 */
import { Router } from "express";
import { assessResume, analyseImprovements, generateRoadmap } from "../ai/careerAgent.js";
import { toLegacyRoadmap } from "../ai/normalize.js";
import { asyncRoute, cleanString, cleanList, httpError } from "./helpers.js";

export function analysisRoutes({ store }) {
  const r = Router();

  async function ensureAssessment(sub) {
    let user = await store.getUser(sub);
    const stale = user.assessment && user.assessment.targetRole !== user.profile.targetRole;
    if (user.resume && (!user.assessment || stale)) {
      const assessment = await assessResume(user);
      user = await store.updateUser(sub, (u) => {
        u.assessment = assessment;
        if (!u.profile.experienceLevel && assessment.experienceLevel) u.profile.experienceLevel = assessment.experienceLevel;
      });
    }
    return user;
  }

  // POST /assessments — score the stored resume against the target role.
  r.post("/assessments", asyncRoute(async (req, res) => {
    const role = cleanString(req.body?.targetRole, 100);
    let user = await store.getUser(req.user.sub);
    if (!user.resume) throw httpError(409, "Upload a resume before running the assessment.");
    if (role && role !== user.profile.targetRole) {
      user = await store.updateUser(req.user.sub, (u) => { u.profile.targetRole = role; });
    }
    const assessment = await assessResume(user);
    await store.updateUser(req.user.sub, (u) => {
      u.assessment = assessment;
      u.improvements = null; // based on the previous assessment
      if (!u.profile.experienceLevel && assessment.experienceLevel) u.profile.experienceLevel = assessment.experienceLevel;
    });
    res.json(assessment);
  }));

  r.get("/assessments/current", asyncRoute(async (req, res) => {
    const user = await store.getUser(req.user.sub);
    if (!user.assessment) throw httpError(404, "No assessment yet.");
    res.json(user.assessment);
  }));

  // POST /analysis/improvements — "What should I improve?"
  r.post("/analysis/improvements", asyncRoute(async (req, res) => {
    const user = await ensureAssessment(req.user.sub);
    if (!user.resume) throw httpError(409, "Upload a resume to get an improvement analysis.");
    const improvements = await analyseImprovements(user);
    await store.updateUser(req.user.sub, (u) => { u.improvements = improvements; });
    res.json(improvements);
  }));

  /**
   * POST /roadmap
   * Beginner mode body (also the legacy contract): { targetRole, experienceLevel, skills, education?, background? }
   * Resume mode: { mode: "resume" } — built from resume + assessment (+ improvements if present).
   * Response: the new roadmap at the top level, plus the legacy { input_mode, target, roadmap } fields.
   */
  r.post("/roadmap", asyncRoute(async (req, res) => {
    const b = req.body || {};
    let user = await store.getUser(req.user.sub);
    const mode = b.mode === "resume" || (b.mode !== "beginner" && user.resume && !b.experienceLevel && !b.skills) ? "resume" : "beginner";

    if (mode === "beginner") {
      const targetRole = cleanString(b.targetRole, 100) || user.profile.targetRole;
      if (!targetRole) throw httpError(400, "Tell us which role you're aiming for first.");
      user = await store.updateUser(req.user.sub, (u) => {
        u.profile.targetRole = targetRole;
        if (b.experienceLevel !== undefined) u.profile.experienceLevel = cleanString(b.experienceLevel, 60);
        if (b.skills !== undefined) u.profile.currentSkills = cleanList(b.skills);
        if (b.background !== undefined) u.profile.background = cleanString(b.background, 600);
        if (b.education !== undefined && b.education) {
          u.profile.education = {
            degree: cleanString(b.education.degree, 120),
            institution: cleanString(b.education.institution, 160),
            graduationYear: cleanString(b.education.graduationYear, 10),
          };
        }
        if (!u.resume) u.profile.path = "beginner";
      });
    } else {
      if (!user.resume) throw httpError(409, "Upload a resume first, or choose the beginner roadmap.");
      user = await ensureAssessment(req.user.sub);
    }

    const roadmap = await generateRoadmap(user, mode);
    await store.updateUser(req.user.sub, (u) => {
      u.roadmap = roadmap;
      u.roadmapProgress = {};
    });
    res.json({
      ...roadmap,
      career_roadmap: roadmap,
      input_mode: "goal_roadmap",
      target: { stated_explicitly: true, target_description: roadmap.targetRole },
      roadmap: toLegacyRoadmap(roadmap),
    });
  }));

  r.get("/roadmap/current", asyncRoute(async (req, res) => {
    const user = await store.getUser(req.user.sub);
    if (!user.roadmap) throw httpError(404, "No roadmap yet.");
    res.json({ roadmap: user.roadmap, progress: user.roadmapProgress });
  }));

  r.patch("/roadmap/progress", asyncRoute(async (req, res) => {
    const stageId = cleanString(req.body?.stageId, 40);
    if (!stageId) throw httpError(400, "stageId is required.");
    const record = await store.updateUser(req.user.sub, (u) => {
      if (!u.roadmap?.stages?.some((s) => s.id === stageId)) throw httpError(404, "That roadmap stage no longer exists.");
      if (req.body.completed) u.roadmapProgress[stageId] = new Date().toISOString();
      else delete u.roadmapProgress[stageId];
    });
    res.json({ progress: record.roadmapProgress });
  }));

  return r;
}
